mapper.select:
SELECT review_id AS reviewId, project_id AS projectId, status, report_markdown AS reportMarkdown,
       create_by AS createBy, create_time AS createTime, complete_by AS completeBy, complete_time AS completeTime
FROM sys_case_review WHERE review_id = #{reviewId}

SELECT item_id AS itemId, review_id AS reviewId, case_id AS caseId, verdict, item_comment AS comment
FROM sys_case_review_item
WHERE review_id = #{reviewId} AND case_id = #{caseId}

mapper.update:
UPDATE sys_case_review_item
SET verdict = #{verdict}, item_comment = #{comment}
WHERE review_id = #{reviewId} AND case_id = #{caseId}

mapper.delete:
DELETE FROM sys_case_review_item
WHERE case_id = #{caseId}
  AND review_id IN (SELECT review_id FROM sys_case_review WHERE status = 'open')
